        "Collection backup exceeds 10 MB." to "Cadangan koleksi melebihi 10 MB.",
        "Backup could not be saved." to "Cadangan belum dapat disimpan.",
        "Backup exceeds 10 MB." to "Cadangan melebihi 10 MB.",
        "Backup could not be read." to "Cadangan tidak dapat dibaca.",
        "Not a supported Yono collection backup." to "Berkas ini bukan cadangan koleksi Yono yang didukung.",
        "Backup field is too long." to "Kolom dalam cadangan terlalu panjang.",
        "Backup tracks must reference local content." to "Lagu dalam cadangan harus merujuk ke konten lokal.",
        "Collections restored. Choose music sources to reconnect unavailable tracks. Original audio was not changed." to "Koleksi dipulihkan. Pilih sumber musik untuk menghubungkan kembali lagu yang belum tersedia. Audio asli tidak diubah.",
        "Not refreshed" to "Belum disinkronkan",
        "Choose music files or a folder in Import. Only your selections are indexed." to "Pilih berkas atau folder musik melalui Impor. Hanya pilihanmu yang dimasukkan ke pustaka.",
        "Choose a document folder." to "Pilih folder melalui pemilih berkas.",
        "Choose a music folder instead of a storage root." to "Pilih folder musik, bukan direktori utama penyimpanan.",
        "Selected music folder indexed" to "Folder musik pilihan ditambahkan ke pustaka.",
        "Folder access needs attention. Select it again in Import." to "Akses folder perlu diperiksa. Pilih kembali melalui Impor.",
        "Music folder" to "Folder musik",
        "Audio file" to "Berkas audio",
        "Chosen files" to "Berkas pilihan",
        "Saved audio could not be read." to "Audio yang disimpan tidak dapat dibaca.",
        "Validated download" to "Unduhan terverifikasi",
        "Give your playlist a name." to "Beri nama daftar putarmu.",
        "User-authorized source" to "Sumber yang diizinkan pengguna",
    )
    fun pesan(value: String): String {
        messages[value]?.let { return it }
        return when {
            value.startsWith("Entry ") && ": " in value -> "Entri " + value.substringAfter("Entry ").substringBefore(": ") + ": " + pesan(value.substringAfter(": "))
            value.startsWith("Row ") -> "Baris " + value.substringAfter("Row ")
            value.startsWith("GitHub returned HTTP ") -> "GitHub merespons HTTP " + value.substringAfter("GitHub returned HTTP ")
            value.startsWith("Commons is unavailable (HTTP ") -> "Commons tidak tersedia (HTTP " + value.substringAfter("Commons is unavailable (HTTP ").substringBefore(")") + "). Coba lagi nanti."
            value.startsWith("Source returned HTTP ") -> "Sumber merespons HTTP " + value.substringAfter("Source returned HTTP ").substringBefore(".") + ". Coba lagi nanti."
            value.startsWith("Selected sources refreshed") -> "Sumber pilihan disinkronkan" + Regex("([0-9]+) need attention").find(value)?.groupValues?.get(1)?.let { " · $it sumber perlu diperiksa melalui Impor" }.orEmpty()
            value.endsWith(" selected files indexed · originals stay in place") -> value.substringBefore(" selected files") + " berkas pilihan ditambahkan ke pustaka · berkas asli tetap di tempatnya"
            value.startsWith("Ambiguous: ") -> "Ada beberapa rekaman lokal yang cocok. Lengkapi artis dan durasi, atau pilih berkas yang tepat."
            value.startsWith("Requested recording was rejected: ") -> "Rekaman yang diminta ditolak: " + pesan(value.substringAfter(": ").removeSuffix(". No audio was published.")) + " Audio tidak dipublikasikan."
            value.startsWith("Collection created. ") -> "Koleksi dibuat. " + Regex("([0-9]+) downloads queued").find(value)?.groupValues?.get(1).orEmpty() + " unduhan masuk antrean; audio yang sudah ada digunakan kembali."
            Regex("^[0-9]+ tracks added to ").containsMatchIn(value) -> value.substringBefore(" tracks added to ") + " lagu ditambahkan ke " + value.substringAfter(" tracks added to ")
            Regex("^[0-9]+ sources ready for review").containsMatchIn(value) -> value.substringBefore(" sources ready") + " sumber siap ditinjau · " + Regex("([0-9]+) failed").find(value)?.groupValues?.get(1).orEmpty() + " gagal" + value.substringAfter("\n", "").takeIf { it.isNotBlank() }?.let { "\n" + it.lineSequence().joinToString("\n") { row -> pesan(row) } }.orEmpty()
            else -> value
        }
    }
    fun pilihan(key: String): String = when (key) {
        "Songs" -> "Lagu"; "Albums" -> "Album"; "Artists" -> "Artis"; "Folders" -> "Folder"
        "Title" -> "Judul"; "Artist" -> "Artis"; "Album" -> "Album"; "Recently added" -> "Baru ditambahkan"; "Duration" -> "Durasi"
        "System" -> "Ikuti sistem"; "Dark" -> "Selalu gelap"; "Light" -> "Selalu terang"
        "Matched" -> "Cocok"; "Unmatched" -> "Belum cocok"; "Duplicate" -> "Duplikat"; "Invalid" -> "Tidak valid"; "Ambiguous" -> "Perlu dipilih"
        "Idle" -> "Belum ada aktivitas"; "Checking" -> "Memeriksa"; "UpToDate" -> "Versi terbaru"; "Error", "Failed" -> "Gagal"
        "Ready" -> "Siap"; "Permission" -> "Perlu izin"; "Available" -> "Tersedia"; "Downloading" -> "Mengunduh"; "Verifying" -> "Memverifikasi"
        "Complete" -> "Selesai"; "Cancelled" -> "Dibatalkan"; "Existing" -> "Sudah ada"; "Queued" -> "Menunggu"; "Saved" -> "Tersimpan"
        "Validating" -> "Memeriksa audio"; "Publishing" -> "Menyimpan"; "Installing" -> "Memasang"; "Confirming" -> "Menunggu konfirmasi"
        else -> key
    }
    fun artis(value: String): String = if (value.isBlank() || value.lowercase() in setOf("unknown artist", "unspecified credits", "<unknown>")) "Artis belum diketahui" else value
    fun album(value: String): String = if (value.isBlank() || value.lowercase() in setOf("unknown album", "<unknown>")) "Album belum diketahui" else value
}
